parameters.text:
=Convert this blog post into a high-engagement Twitter/X thread.

Author: {{ $('Set Blog URL').item.json.author_handle }}
Style: {{ $('Set Blog URL').item.json.thread_style }}

Blog Content:
{{ $json.data }}

Rules:
- Tweet 1: Hook — make people stop scrolling (under 200 chars, no 'Thread:' or numbering)
- Tweets 2-8: One insight per tweet, max 250 chars each
- Tweet 9: Controversial or surprising takeaway
- Tweet 10: CTA + follow ask
- Each tweet must stand alone
- No filler, no generic advice
- Conversational, not corporate

Return JSON:
{
  "thread": [
    {"tweet_number": 1, "text": "", "type": "hook"},
    {"tweet_number": 2, "text": "", "type": "insight"}
  ],
  "thread_topic": "",
  "estimated_reach": "low/medium/high"
}

parameters.jsCode:
const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const data = JSON.parse(raw);
return [{ json: data }];

const thread = $input.item.json.thread;
const formatted = thread.map((t,i) => `${i+1}/${thread.length}
${t.text}`).join('

---

');
return [{ json: { formatted_thread: formatted, tweet_count: thread.length, hook: thread[0].text, topic: $input.item.json.thread_topic } }];
